// The exported `fin` command registry (sub-project 7B Decision 1, spec §7.2): every command's
// name, group, the RPCs it sends and the payload fields that identify it. Generated by
// `fin schema --registry` into `../registry.json` (never hand-written; the gate
// `scripts/check-registry.mjs` fails on drift). Only the shape is declared here, as a schema the
// JSON is decoded through when the module loads; the types are derived from it.
import { Schema } from "effect";
import registryJson from "../registry.json" with { type: "json" };

/**
 * A condition on one payload field (a dotted path; a `*` segment stands for any element of an
 * array): a string or boolean is equality with any value at that path, `{present}` is whether the
 * field holds a value (a `null` is none).
 */
export const RegistryMatchSchema = Schema.Union([Schema.String, Schema.Boolean, Schema.Struct({ present: Schema.Boolean })]);
export type RegistryMatch = typeof RegistryMatchSchema.Type;

export const RegistryRpcSchema = Schema.Struct({
  method: Schema.String,
  /** All of these hold for the RPC to be this command's; absent: any payload. */
  match: Schema.optionalKey(Schema.Record(Schema.String, RegistryMatchSchema)),
});
export type RegistryRpc = typeof RegistryRpcSchema.Type;

export const RegistryCommandSchema = Schema.Struct({
  /** `item.trim`, or the plugin-command pattern `plugin:<id>/<command>` (`dynamic`). */
  name: Schema.String,
  group: Schema.String,
  /** Any one of these is the command; none: a client-side command or a shared helper's. */
  rpcs: Schema.Array(RegistryRpcSchema),
  /** The payload fields that say what the command acts on (an approval card's subject). */
  identity: Schema.Array(Schema.String),
  write: Schema.Boolean,
  /** Arguments that name a client-side file (`path`). */
  argKinds: Schema.Record(Schema.String, Schema.Literal("path")),
  /** Plugin commands: the name is composed by the server from the plugin host's record. */
  dynamic: Schema.optionalKey(Schema.Boolean),
});
export type RegistryCommand = typeof RegistryCommandSchema.Type;

export const RegistrySchema = Schema.Struct({
  version: Schema.Number,
  commands: Schema.Array(RegistryCommandSchema),
});
export type Registry = typeof RegistrySchema.Type;

export const REGISTRY: Registry = Schema.decodeUnknownSync(RegistrySchema)(registryJson);
